 20	class MockRepositoryManager {
 21	    private store: Repository[] = [];
 22	
 23	    list(): Repository[] {
 24	        return this.store;
 25	    }
 26	
 27	    getById(id: string): Repository | undefined {
 28	        return this.store.find((r) => r.Id === id);
 29	    }
 30	
 31	    exists(id: string): boolean {
 32	        return this.getById(id) !== undefined;
 33	    }
 34	
 35	    add(params: { url: string; name?: string; id?: string }): Repository {
 36	        const id = params.id ?? 'inferred-id';
 37	        const name = params.name ?? id;
 38	
 39	        const duplicate = this.store.find((r) => r.Id === id);
 40	        if (duplicate) {
 41	            throw new Error(`A repository with ID "${id}" already exists.`);
 42	        }
 43	
 44	        const duplicateUrl = this.store.find((r) => r.Url === params.url);
 45	        if (duplicateUrl) {
 46	            throw new Error(`A repository with URL "${params.url}" already exists (ID: "${duplicateUrl.Id}").`);
 47	        }
 48	
 49	        const repo: Repository = { Id: id, Name: name, Url: params.url };
 50	        this.store.push(repo);
 51	        return repo;
 52	    }
 53	
 54	    update(id: string, params: { name: string }): Repository {
 55	        const index = this.store.findIndex((r) => r.Id === id);
 56	        if (index === -1) {
 57	            throw new NotFoundError(`Cannot update: repository with ID "${id}" does not exist.`);
 58	        }
 59	        this.store[index] = { ...this.store[index], Name: params.name };
 60	        return this.store[index];
 61	    }
 62	
 63	    remove(id: string): void {
 64	        const index = this.store.findIndex((r) => r.Id === id);
 65	        if (index === -1) {
 66	            throw new NotFoundError(`Cannot remove: repository with ID "${id}" does not exist.`);
 67	        }
 68	        this.store.splice(index, 1);
 69	    }
