  1	/**
  2	 * Shared HTTP mock helpers for server-layer unit tests.
  3	 *
  4	 * Provides lightweight in-process fakes for Node's `IncomingMessage` and
  5	 * `ServerResponse` objects so route handlers can be tested without standing up
  6	 * a real HTTP server.
  7	 *
  8	 * **Exports**
  9	 * - `mockRequest(method, url, bodyJson?)` — builds a fake `IncomingMessage` that
 10	 *   emits `data` + `end` (or just `end`) on the next tick, and emits `error` on
 11	 *   `.destroy()`.
 12	 * - `MockResponse` — interface capturing the result of a handler call
 13	 *   (`statusCode`, `headers`, `body`, raw `res`).
 14	 * - `mockResponse()` — builds a `MockResponse` whose `.res` intercepts
 15	 *   `writeHead()` and `end()` calls so assertions can inspect status codes and
 16	 *   response bodies. `statusCode` starts as `undefined` (not `0`) so tests can
 17	 *   distinguish "handler never wrote a response" from a deliberate `200`.
 18	 * - `MockStreamResponse` — interface for streaming responses that capture
 19	 *   `endCalled` and `piped` flags instead of a body string (used by
 20	 *   `staticServer.test.ts` where responses are piped via `ReadStream.pipe(res)`).
 21	 * - `mockStreamResponse()` — builds a `MockStreamResponse` whose `.res` accepts
 22	 *   `writeHead()`, `end()`, and `write()` (the minimum a piped stream needs).
 23	 * - `flushAsync()` — awaits two `process.nextTick` callbacks, giving async route
 24	 *   handlers and event emitters time to run before assertions fire.
 25	 *
 26	 * **Consumers**
 27	 * - `src/server/__tests__/routes/branches.test.ts`
 28	 * - `src/server/__tests__/routes/config.test.ts`
 29	 * - `src/server/__tests__/routes/error-log.test.ts`
 30	 * - `src/server/__tests__/routes/notes.test.ts`
 31	 * - `src/server/__tests__/routes/projects.test.ts`
 32	 * - `src/server/__tests__/routes/repositories.test.ts`
 33	 * - `src/server/__tests__/routes/status.test.ts`
 34	 * - `src/server/__tests__/routes/workspaces.test.ts`
 35	 * - `src/server/__tests__/routes/workspaces-health.test.ts`
 36	 * - `src/server/__tests__/routes/workspaces-launch.test.ts`
 37	 * - `src/server/__tests__/config.notes-display.test.ts`
 38	 * - `src/server/__tests__/requestUtils.test.ts`
 39	 * - `src/server/__tests__/router.test.ts`
 40	 * - `src/server/__tests__/staticServer.test.ts`
 41	 */
 42	import { EventEmitter } from 'node:events';
 43	import type { IncomingMessage, ServerResponse } from 'node:http';
 44	
 45	export function mockRequest(method: string, url: string, bodyJson?: unknown): IncomingMessage {
 46	    const req = new EventEmitter() as IncomingMessage;
 47	    (req as unknown as { method: string }).method = method;
 48	    (req as unknown as { url: string }).url = url;
 49	    (req as unknown as { destroy(): void }).destroy = () => {
 50	        req.emit('error', new Error('destroyed'));
 51	    };
 52	
 53	    process.nextTick(() => {
 54	        if (bodyJson !== undefined) {
 55	            req.emit('data', Buffer.from(JSON.stringify(bodyJson)));
 56	        }
 57	        req.emit('end');
 58	    });
 59	
 60	    return req;
 61	}
 62	
